--##################
--## KEYBINDINGS ###
--##################

-- See https://wiki.hyprland.org/Configuring/Keywords/
-- Generated by hyprlang2lua.

local mainMod = "SUPER" -- Sets "Windows" key as main modifier
local scdMod = "ALT" -- Sets alt as second mod key

-- Binds to run some apps
hl.bind(mainMod .. " + Return", hl.dsp.exec_cmd("$terminal"))
hl.bind(mainMod .. " + F", hl.dsp.exec_cmd("$webBrowser"))
hl.bind(mainMod .. " + E", hl.dsp.exec_cmd("$fileManager"))
hl.bind(mainMod .. " + L_SHIFT + E", hl.dsp.exec_cmd("$fileManagerBis"))
hl.bind(mainMod .. " + space", hl.dsp.exec_cmd("$menu"))
hl.bind(scdMod .. " + space", hl.dsp.exec_cmd("$menu"))
hl.bind(mainMod .. " + O", hl.dsp.exec_cmd("obsidian"))

-- Some binds
hl.bind(mainMod .. " + C", hl.dsp.window.close())
hl.bind(mainMod .. " + M", hl.dsp.exit())
hl.bind(mainMod .. " + V", hl.dsp.window.float({ action = "toggle" }))
hl.bind(mainMod .. " + P", hl.dsp.window.pseudo())
-- bind = $mainMod, J, togglesplit, # dwindle
hl.bind(mainMod .. " + J", hl.dsp.layout("togglesplit"), { description = "$d toggle split" })
hl.bind(mainMod .. " + & + CTRL + F", hl.dsp.window.fullscreen({ mode = "fullscreen", action = "toggle" }))

-- An exit menu
-- bind = CTRL & ALT, Delete, exec, $HOME/.config/home-manager/graphical-env/hypr/scripts/exit_menu.sh
-- bind = CTRL & ALT, Delete, exec, wlogout
hl.bind("CTRL + & + ALT + Delete", hl.dsp.exec_cmd("noctalia msg panel-toggle session"))

-- Lock the screen and suspend after 30 sec
hl.bind(mainMod .. " + L", hl.dsp.exec_cmd("$HOME/.config/home-manager/graphical-env/hypr/scripts/manualLock.sh"), { locked = true })

--activate/deactivate autosuspend :
hl.bind(mainMod .. " + & + L_Shift + L", hl.dsp.exec_cmd("$HOME/.config/home-manager/graphical-env/hypr/scripts/toggle_autosuspend.sh"), { locked = true })

-- Waybar keybinds
hl.bind(mainMod .. " + B", hl.dsp.exec_cmd("$HOME/.config/home-manager/graphical-env/hypr/scripts/toggleWaybar.sh"))
hl.bind(mainMod .. " + & + L_Shift + B", hl.dsp.exec_cmd("pkill -9 waybar; waybar;"))

-- Change wallpaper and theme
hl.bind(mainMod .. " + & + CTRL + & + L_Shift + W", hl.dsp.exec_cmd("$HOME/.config/home-manager/graphical-env/hypr/scripts/wallpapers/load_rand_wall.sh"))
hl.bind(mainMod .. " + & + CTRL + W", hl.dsp.exec_cmd("$HOME/.config/home-manager/graphical-env/hypr/scripts/wallpapers/select_wall.sh"))

-- Screenshot
hl.bind(mainMod .. " + & + L_Shift + S", hl.dsp.exec_cmd("hyprshot -zm region"))
hl.bind("PRINT", hl.dsp.exec_cmd("hyprshot -m output -m active"))

-- to switch between windows in a floating workspace
hl.bind(scdMod .. " + Tab", hl.dsp.window.cycle_next({ next = true }))
hl.bind(scdMod .. " + Tab", hl.dsp.window.bring_to_top())

-- Move focus with mainMod + arrow keys
hl.bind(mainMod .. " + left", hl.dsp.focus({ direction = "left" }), { repeating = true })
hl.bind(mainMod .. " + right", hl.dsp.focus({ direction = "right" }), { repeating = true })
hl.bind(mainMod .. " + up", hl.dsp.focus({ direction = "up" }), { repeating = true })
hl.bind(mainMod .. " + down", hl.dsp.focus({ direction = "down" }), { repeating = true })

-- Move window with mainMod + shift(or CTRL) + arrow keys
hl.bind("$mainMod&SHIFT + left", hl.dsp.window.move({ direction = "l" }), { repeating = true })
hl.bind("$mainMod&SHIFT + right", hl.dsp.window.move({ direction = "r" }), { repeating = true })
hl.bind("$mainMod&SHIFT + up", hl.dsp.window.move({ direction = "u" }), { repeating = true })
hl.bind("$mainMod&SHIFT + down", hl.dsp.window.move({ direction = "d" }), { repeating = true })
hl.bind("$mainMod&Ctrl + left", hl.dsp.window.move({ direction = "l" }), { repeating = true })
hl.bind("$mainMod&Ctrl + right", hl.dsp.window.move({ direction = "r" }), { repeating = true })
hl.bind("$mainMod&Ctrl + up", hl.dsp.window.move({ direction = "u" }), { repeating = true })
hl.bind("$mainMod&Ctrl + down", hl.dsp.window.move({ direction = "d" }), { repeating = true })

-- Focus mode :
hl.bind(mainMode .. " + & + SHIFT + F", hl.dsp.exec_cmd("$HOME/.config/home-manager/graphical-env/hypr/scripts/focus_mode.sh"), { repeating = true })

-- Resize windows :
hl.bind(mainMod .. " + R", hl.dsp.exec_cmd("dunstify -t 1500 \"Resizing mode\" \"You are in resizing mode, type echap key to quit\""), { transparent = true })
hl.bind(mainMod .. " + R", hl.dsp.submap("resize"), { transparent = true })

hl.define_submap("resize", function()
    hl.bind("right", hl.dsp.window.resize({ x = 20, y = 0, relative = true }), { repeating = true })
    hl.bind("left", hl.dsp.window.resize({ x = -20, y = 0, relative = true }), { repeating = true })
    hl.bind("up", hl.dsp.window.resize({ x = 0, y = -20, relative = true }), { repeating = true })
    hl.bind("down", hl.dsp.window.resize({ x = 0, y = 20, relative = true }), { repeating = true })
    hl.bind("Shift_L + right", hl.dsp.window.resize({ x = 100, y = 0, relative = true }), { repeating = true })
    hl.bind("Shift_L + left", hl.dsp.window.resize({ x = -100, y = 0, relative = true }), { repeating = true })
    hl.bind("Shift_L + up", hl.dsp.window.resize({ x = 0, y = -100, relative = true }), { repeating = true })
    hl.bind("Shift_L + down", hl.dsp.window.resize({ x = 0, y = 100, relative = true }), { repeating = true })

      -- use reset to go back to the global submap
    hl.bind(mainMod .. " + R", hl.dsp.submap("reset"))
    hl.bind("Escape", hl.dsp.submap("reset"))
      -- bindt = , catchall, submap, reset
end)

-- Switch workspaces with mainMod + [0-9]
hl.bind(mainMod .. " + code:10", hl.dsp.focus({ workspace = 1 }))
hl.bind(mainMod .. " + code:11", hl.dsp.focus({ workspace = 2 }))
hl.bind(mainMod .. " + code:12", hl.dsp.focus({ workspace = 3 }))
hl.bind(mainMod .. " + code:13", hl.dsp.focus({ workspace = 4 }))
hl.bind(mainMod .. " + code:14", hl.dsp.focus({ workspace = 5 }))
hl.bind(mainMod .. " + code:15", hl.dsp.focus({ workspace = 6 }))
hl.bind(mainMod .. " + code:16", hl.dsp.focus({ workspace = 7 }))
hl.bind(mainMod .. " + code:17", hl.dsp.focus({ workspace = 8 }))
hl.bind(mainMod .. " + code:18", hl.dsp.focus({ workspace = 9 }))
hl.bind(mainMod .. " + code:19", hl.dsp.focus({ workspace = 10 }))

-- Move active window to a workspace with mainMod + SHIFT + [0-9]
hl.bind(mainMod .. " + SHIFT + code:10", hl.dsp.window.move({ workspace = 1 }))
hl.bind(mainMod .. " + SHIFT + code:11", hl.dsp.window.move({ workspace = 2 }))
hl.bind(mainMod .. " + SHIFT + code:12", hl.dsp.window.move({ workspace = 3 }))
hl.bind(mainMod .. " + SHIFT + code:13", hl.dsp.window.move({ workspace = 4 }))
hl.bind(mainMod .. " + SHIFT + code:14", hl.dsp.window.move({ workspace = 5 }))
hl.bind(mainMod .. " + SHIFT + code:15", hl.dsp.window.move({ workspace = 6 }))
hl.bind(mainMod .. " + SHIFT + code:16", hl.dsp.window.move({ workspace = 7 }))
hl.bind(mainMod .. " + SHIFT + code:17", hl.dsp.window.move({ workspace = 8 }))
hl.bind(mainMod .. " + SHIFT + code:18", hl.dsp.window.move({ workspace = 9 }))
hl.bind(mainMod .. " + SHIFT + code:19", hl.dsp.window.move({ workspace = 10 }))

-- Special workspace
hl.bind(mainMod .. " + W", hl.dsp.workspace.toggle_special("magic"))
hl.bind(mainMod .. " + SHIFT + W", hl.dsp.window.move({ workspace = "special:magic" }))
hl.bind(mainMod .. " + D", hl.dsp.focus({ workspace = "name:D" }))
hl.bind(mainMod .. " + SHIFT + D", hl.dsp.window.move({ workspace = "name:D" }))

-- Scroll through existing workspaces with mainMod + scroll
hl.bind(mainMod .. " + mouse_down", hl.dsp.focus({ workspace = "e+1" }))
hl.bind(mainMod .. " + mouse_up", hl.dsp.focus({ workspace = "e-1" }))

-- Move/resize windows with mainMod + LMB/RMB and dragging
hl.bind(mainMod .. " + mouse:272", hl.dsp.window.drag())
hl.bind(mainMod .. " + mouse:273", hl.dsp.window.resize())

-- Global shortcuts :
hl.bind("insert", hl.dsp.global(":Discord"), { non_consuming = true })

-- Laptop multimedia keys for volume and LCD brightness
-- Volume
hl.bind("XF86AudioMute", hl.dsp.exec_cmd("wpctl set-mute @DEFAULT_AUDIO_SINK@ toggle"), { locked = true, repeating = true })
hl.bind("XF86AudioMicMute", hl.dsp.exec_cmd("wpctl set-mute @DEFAULT_AUDIO_SOURCE@ toggle"), { locked = true, repeating = true })
hl.bind("XF86AudioRaiseVolume", hl.dsp.exec_cmd("wpctl set-volume @DEFAULT_AUDIO_SINK@ 5%+"), { locked = true, repeating = true })
hl.bind("XF86AudioLowerVolume", hl.dsp.exec_cmd("wpctl set-volume @DEFAULT_AUDIO_SINK@ 5%-"), { locked = true, repeating = true })

-- Brightness
hl.bind("XF86MonBrightnessUp", hl.dsp.exec_cmd("brightnessctl s 5%+"), { locked = true, repeating = true })
--bindel = ,XF86MonBrightnessUp, exec, $HOME/.config/home-manager/graphical-env/hypr/scripts/displayBrightness.sh
hl.bind("XF86MonBrightnessDown", hl.dsp.exec_cmd("brightnessctl s 5%-"), { locked = true, repeating = true })
--bindel = ,XF86MonBrightnessDown, exec, $HOME/.config/home-manager/graphical-env/hypr/scripts/displayBrightness.sh
--Brightness for 2nd keyboard : 
hl.bind(mainMod .. " + F1", hl.dsp.exec_cmd("brightnessctl s 5%-"), { locked = true, repeating = true })
hl.bind(mainMod .. " + F1", hl.dsp.exec_cmd("$HOME/.config/home-manager/graphical-env/hypr/scripts/displayBrightness.sh"), { locked = true, repeating = true })
hl.bind(mainMod .. " + F2", hl.dsp.exec_cmd("brightnessctl s 5%+"), { locked = true, repeating = true })
hl.bind(mainMod .. " + F2", hl.dsp.exec_cmd("$HOME/.config/home-manager/graphical-env/hypr/scripts/displayBrightness.sh"), { locked = true, repeating = true })

hl.bind("XF86Calculator", hl.dsp.exec_cmd("kalk"))

--
--# Zoom :
--
hl.bind(mainMod .. " + SHIFT + mouse_down", hl.dsp.exec_cmd("hyprctl -q keyword cursor:zoom_factor $(hyprctl getoption cursor:zoom_factor -j | jq '.float * 1.1')"))
hl.bind(mainMod .. " + SHIFT + mouse_up", hl.dsp.exec_cmd("hyprctl -q keyword cursor:zoom_factor $(hyprctl getoption cursor:zoom_factor -j | jq '(.float * 0.9) | if . < 1 then 1 else . end')"))

hl.bind(mainMod .. " + equal", hl.dsp.exec_cmd("hyprctl -q keyword cursor:zoom_factor $(hyprctl getoption cursor:zoom_factor -j | jq '.float * 1.1')"), { repeating = true })

-- reset zoom :
hl.bind(mainMod .. " + SHIFT + minus", hl.dsp.exec_cmd("hyprctl -q keyword cursor:zoom_factor 1"))
hl.bind(mainMod .. " + SHIFT + equal", hl.dsp.exec_cmd("hyprctl -q keyword cursor:zoom_factor 1"))
hl.bind(mainMod .. " + SHIFT + 0", hl.dsp.exec_cmd("hyprctl -q keyword cursor:zoom_factor 1"))

